local ADDON_NAME = ...

local L = LibStub("AceLocale-3.0"):NewLocale(ADDON_NAME, "deDE")
if not L then return end

L["General"] = "Allgemein"
L["Travel: mount and travel form"] = "Travel: Reittier und Reisegestalt"
L["Travel with a double click"] = "Reisen per Doppelklick"
L["A double click on the game world with the key below mounts up or dismounts. If no mount is allowed or you cannot ride yet, your class ability for faster travel is used (Travel Form, Ghost Wolf, Aspect of the Cheetah). In water: Aquatic Form or a swim speed potion. If none of these is possible: a speed ability (Sprint, Dash) or a speed potion. Only out of combat."] = "Ein Doppelklick in die Spielwelt mit der Taste unten setzt dich auf dein Reittier oder lässt dich absteigen. Ist kein Reittier erlaubt oder kannst du noch nicht reiten, wird deine Klassenfertigkeit für schnelleres Reisen benutzt (Reisegestalt, Geisterwolf, Aspekt des Geparden). Im Wasser: Wassergestalt oder ein Schwimmtrank. Geht nichts davon: eine Tempo-Fähigkeit (Sprinten, Spurt) oder ein Tempotrank. Nur außerhalb des Kampfes."
L["Mount up automatically"] = "Automatisch aufsitzen"
L["The double click summons a mount: a favorite if you have one, otherwise any usable mount. A second double click dismounts."] = "Der Doppelklick ruft ein Reittier: einen Favoriten, wenn du einen hast, sonst ein beliebiges nutzbares Reittier. Ein weiterer Doppelklick lässt dich absteigen."
L["Use a class ability to travel faster"] = "Klassenfertigkeit für schnelleres Reisen benutzen"
L["Used when no mount is allowed here or you cannot ride yet, and in water for Aquatic Form. A second double click leaves the form."] = "Wird benutzt, wenn hier kein Reittier erlaubt ist oder du noch nicht reiten kannst, und im Wasser für die Wassergestalt. Ein weiterer Doppelklick hebt die Gestalt auf."
L["Drink a swim speed potion in water"] = "Im Wasser einen Schwimmtrank trinken"
L["Only when no Aquatic Form is available. Uses up one potion."] = "Nur, wenn keine Wassergestalt verfügbar ist. Verbraucht einen Trank."
L["Current key: %s"] = "Aktuelle Taste: %s"
L["Shows the travel settings, what the client reports about mounts and travel abilities, the current ride and the last double clicks: /gli travel"] = "Zeigt die Reise-Einstellungen, was der Client zu Reittieren und Reisefertigkeiten meldet, die laufende Fahrt und die letzten Doppelklicks: /gli travel"
L["Flight map"] = "Flugkarte"
L["Show the flight time in the tooltip"] = "Flugzeit im Tooltip anzeigen"
L["Hover a flight point on the flight map to see how long the flight from here takes, measured by Glimpse on your characters. Routes you never flew in one go are estimated from their measured legs."] = "Zeigt beim Überfahren eines Flugpunkts auf der Flugkarte, wie lange der Flug von hier dauert, gemessen von Glimpse auf deinen Charakteren. Strecken, die du noch nie am Stück geflogen bist, werden aus ihren gemessenen Teilstrecken geschätzt."
L["Flight time: %s"] = "Flugzeit: %s"
L["Flight time: about %s"] = "Flugzeit: etwa %s"
L["not measured yet"] = "noch nicht gemessen"
L["Average of %d flights"] = "Durchschnitt aus %d Flügen"
L["From %d measured legs"] = "Aus %d gemessenen Teilstrecken"
L["Measured on one flight"] = "Gemessen bei einem Flug"
L["Use a speed ability (Sprint, Dash)"] = "Tempo-Fähigkeit benutzen (Sprinten, Spurt)"
L["Used when neither a mount nor a travel form is possible, also in water. Skipped while its cooldown runs. Dash only works in Cat Form."] = "Wird benutzt, wenn weder Reittier noch Reisegestalt gehen, auch im Wasser. Läuft die Abklingzeit, wird sie übersprungen. Spurt geht nur in Katzengestalt."
L["Drink a speed potion"] = "Tempotrank trinken"
L["Swiftness Potion from your bags, when neither a mount, a travel form nor a speed ability is possible. Uses up one potion."] = "Beweglichkeitstrank aus den Taschen, wenn weder Reittier, Reisegestalt noch Tempo-Fähigkeit gehen. Verbraucht einen Trank."
L["Arrival"] = "Ankunft"
L["Show a countdown to the arrival"] = "Countdown bis zur Ankunft anzeigen"
L["On the Deeprun Tram and on flight routes a green line at the top of the screen counts down to the arrival, from the travel and flight times Glimpse knows."] = "In der Tiefenbahn und auf Flugrouten zählt oben am Bildschirm eine grüne Zeile bis zur Ankunft herunter, aus den Fahr- und Flugzeiten, die Glimpse kennt."
L["Play a sound shortly before the arrival"] = "Kurz vor der Ankunft einen Ton spielen"
L["5 seconds before the arrival."] = "5 Sekunden vor der Ankunft."
L["Show notes during the Deeprun Tram ride"] = "Hinweise während der Tiefenbahn-Fahrt anzeigen"
L["During the ride, short notes appear in white: right after departure, at a quarter, half and three quarters of the way, and on arrival."] = "Während der Fahrt erscheinen kurze Hinweise in Weiß: direkt nach der Abfahrt, nach einem Viertel, der Hälfte und drei Vierteln der Strecke und bei der Ankunft."
